import Foundation
import Vision
import CoreImage
import CoreVideo
import CoreGraphics

/// The model owns only its actual low-resolution instance mask. Full-resolution
/// guide/refinement uses the same float source and bounded global running fields.
/// No AI pixels are regenerated by a later RAW recipe edit.
nonisolated enum LWFloatSubjectMask {
    private final class RequestOwner: @unchecked Sendable {
        let request=VNGenerateForegroundInstanceMaskRequest()
    }
    static func run(_ source:LWFloatPlane,settings:FilterSettings,workspace:LWFloatWorkspace)throws->LWFloatPlane {
        let provider=LWFloatPlaneImage(plane:source,cancellation:workspace.cancellation),image=try provider.image()
        let owner=RequestOwner(),registration=workspace.cancellation.register { owner.request.cancel() }
        defer { registration.remove() }
        try workspace.cancellation.check()
        let handler=VNImageRequestHandler(cgImage:image,orientation:.up)
        try handler.perform([owner.request]);try provider.check();try workspace.cancellation.check()
        guard let observation=owner.request.results?.first,!observation.allInstances.isEmpty else { throw SubjectRemoval.Failure.noSubject }
        // SDK VNObservation.h explicitly gives OneComponent32Float, analysis
        // resolution, without allocating a full-resolution mask buffer.
        let buffer=try observation.generateMask(forInstances:observation.allInstances)
        guard CVPixelBufferGetPixelFormatType(buffer)==kCVPixelFormatType_OneComponent32Float,
            CVPixelBufferLockBaseAddress(buffer,.readOnly)==kCVReturnSuccess else { throw ProjectError.invalid }
        defer { CVPixelBufferUnlockBaseAddress(buffer,.readOnly) }
        let width=CVPixelBufferGetWidth(buffer),height=CVPixelBufferGetHeight(buffer),stride=CVPixelBufferGetBytesPerRow(buffer)
        try LWFloatPlane.validateExtent(width:width,height:height)
        let rowBytes=width.multipliedReportingOverflow(by:4),bufferBytes=stride.multipliedReportingOverflow(by:height)
        guard !rowBytes.overflow,!bufferBytes.overflow,stride>=rowBytes.partialValue,
            let base=CVPixelBufferGetBaseAddress(buffer) else { throw ProjectError.invalid }
        let lease=try workspace.workingSet.reserve(bufferBytes.partialValue)
        let builder=try workspace.makeBuilder(width:width,height:height)
        while let range=builder.nextRange {
            try workspace.cancellation.check()
            let bytes=try range.validate(frameWidth:width,frameHeight:height),tileLease=try workspace.workingSet.reserve(bytes)
            var pixels=[SIMD4<Float>]();pixels.reserveCapacity(bytes/16)
            for y in range.y..<range.y+range.height { for x in range.x..<range.x+range.width {
                let value=base.advanced(by:y*stride+x*4).loadUnaligned(as:Float.self)
                guard value.isFinite,(0...1).contains(value) else { throw ProjectError.invalid };pixels.append(SIMD4(repeating:value))
            } }
            try builder.append(LWLinearSurface(width:range.width,height:range.height,pixels:pixels,maximumBytes:bytes),at:range)
            withExtendedLifetime(tileLease) {}
        }
        let small=try builder.finish()
        var result=try resampleCoverage(small,width:source.width,height:source.height,workspace:workspace)
        if settings.backgroundQuality == .advanced {
            if settings.refineEdges>0 { result=try guided(result,source:source,radius:max(1,Int(settings.refineEdges.rounded())),workspace:workspace) }
            if settings.shiftEdge != 0 {
                let reach=abs(settings.shiftEdge),soft=try LWFloatFilter.coreImage(result,workspace:workspace) { $0.clampedToExtent().applyingGaussianBlur(sigma:reach/2) }
                let level:Float=settings.shiftEdge<0 ? 0.75:0.25
                result=try LWFloatCompositor.map(soft,workspace:workspace) { p,_,_ in
                    let value=min(1,max(0,(min(level+0.001,max(level,p.x))-level)/0.001));return SIMD4(repeating:value)
                }
            }
            if settings.matteContrast>0 {
                let strength=Float(settings.matteContrast/100),slope=1/max(0.02,1-strength*0.98)
                result=try LWFloatCompositor.map(result,workspace:workspace) { p,_,_ in SIMD4(repeating:min(1,max(0,p.x*slope+(1-slope)/2))) }
            }
        }
        withExtendedLifetime(lease) {};return result
    }
    /// Global pixel-center coordinates match LWFloatPlane.Sampler. Coverage
    /// interpolates alpha directly; straight color is not a scalar mask sample.
    static func resampleCoverage(_ small:LWFloatPlane,width:Int,height:Int,workspace:LWFloatWorkspace)throws->LWFloatPlane {
        let sampler=small.sampler(edge:.clamp)
        let blank=try LWFloatCompositor.clearPlane(width:width,height:height,workspace:workspace)
        return try LWFloatCompositor.map(blank,workspace:workspace) { _,x,y in
            let point=CGPoint(x:(Double(x)+0.5)*Double(small.width)/Double(width),
                y:(Double(y)+0.5)*Double(small.height)/Double(height))
            let value=try sampler.sample(point).w
            guard value.isFinite,(0...1).contains(value) else { throw ProjectError.invalid }
            return SIMD4(repeating:value)
        }
    }
    /// The retained He/Sun/Tang equations and row/column running order. Scalar
    /// records store Float-rounded values in f64 slots; no whole-frame arrays.
    static func guided(_ mask:LWFloatPlane,source:LWFloatPlane,radius:Int,workspace:LWFloatWorkspace)throws->LWFloatPlane {
        let w=source.width,h=source.height
        guard mask.width==w,mask.height==h,(1...40).contains(radius) else { throw ProjectError.invalid }
        let kernel=LWFloatKernelWorkspace(makeBuilder:{try workspace.makeBuilder(width:$0,height:$1)},makeScratchDirectory:{try workspace.makeScratchDirectory()},fileOwner:workspace)
        let g=try kernel.scalar(source) { p in
            typealias K=FloatImageAdjustmentPixels
            return Double(Float(K.luminance(SIMD3(K.encode(Double(p.x)),K.encode(Double(p.y)),K.encode(Double(p.z))))))
        },m=try kernel.scalar(mask) { Double($0.x) }
        func field(_ f:(Int,Int)throws->Float)throws->LWFloatDoubleRows {
            try LWFloatDoubleRows.create(width:w,height:h,workingSet:workspace.workingSet,directory:workspace.makeScratchDirectory(),fileOwner:workspace) { y in
                var row=[Double]();row.reserveCapacity(w)
                for x in 0..<w { row.append(Double(try f(x,y))) };return row
            }
        }
        func box(_ value:LWFloatDoubleRows)throws->LWFloatDoubleRows {
            let span=Float(radius*2+1)
            let horizontal=try LWFloatDoubleRows.create(width:w,height:h,workingSet:workspace.workingSet,directory:workspace.makeScratchDirectory(),fileOwner:workspace) { y in
                let row=try value.read(y);var output=[Double](repeating:0,count:w),sum:Float=0
                for x in -radius...radius { sum += Float(row.values[min(w-1,max(0,x))]) }
                for x in 0..<w { output[x]=Double(sum/span);sum -= Float(row.values[min(w-1,max(0,x-radius))]);sum += Float(row.values[min(w-1,max(0,x+radius+1))]) };return output
            }
            // Column accumulators are an admitted row; output is written row-major.
            let charge=try workspace.workingSet.reserve(w*MemoryLayout<Float>.stride)
            var sums=[Float](repeating:0,count:w)
            for y in -radius...radius { let row=try horizontal.read(min(h-1,max(0,y)));for x in 0..<w { sums[x] += Float(row.values[x]) } }
            let output=try LWFloatDoubleRows.create(width:w,height:h,workingSet:workspace.workingSet,directory:workspace.makeScratchDirectory(),fileOwner:workspace) { y in
                let row=sums.map { Double($0/span) },remove=try horizontal.read(min(h-1,max(0,y-radius))),add=try horizontal.read(min(h-1,max(0,y+radius+1)))
                for x in 0..<w { sums[x] -= Float(remove.values[x]);sums[x] += Float(add.values[x]) };return row
            };withExtendedLifetime(charge) {};return output
        }
        let meanG=try box(g),meanM=try box(m),square=try field { x,y in let v=Float(try g.value(x:x,y:y));return v*v }
        let product=try field { x,y in Float(try g.value(x:x,y:y))*Float(try m.value(x:x,y:y)) }
        let meanSquare=try box(square),meanProduct=try box(product)
        let a=try field { x,y in
            let guide=Float(try meanG.value(x:x,y:y)),mask=Float(try meanM.value(x:x,y:y))
            let variance=Float(try meanSquare.value(x:x,y:y))-guide*guide,covariance=Float(try meanProduct.value(x:x,y:y))-guide*mask
            return covariance/(variance+1e-4)
        },b=try field { x,y in Float(try meanM.value(x:x,y:y))-Float(try a.value(x:x,y:y))*Float(try meanG.value(x:x,y:y)) }
        let meanA=try box(a),meanB=try box(b)
        return try LWFloatCompositor.map(mask,workspace:workspace) { _,x,y in
            let value=min(1,max(0,Float(try meanA.value(x:x,y:y))*Float(try g.value(x:x,y:y))+Float(try meanB.value(x:x,y:y))))
            return SIMD4(repeating:value)
        }
    }
}
